import { placeFood, stepSnake } from "./shared-rules.js";

const $=selector=>document.querySelector(selector),canvas=$("#game"),ctx=canvas.getContext("2d"),W=24,H=18,CELL=30;
const SPEEDS={relaxed:{name:"清风",delay:170},normal:{name:"疾风",delay:125},storm:{name:"惊风",delay:85}};
let snake=[],food=null,direction={x:1,y:0},queued={x:1,y:0},score=0,best=Number(localStorage.getItem("bambooSnakeBest")||0),speed="normal",running=false,paused=false,ended=false,timer=null,touchStart=null,toastTimer;
let soundEnabled=sessionStorage.getItem("bambooSnakeSound")!=="off",audioContext=null;
function tone(freq=440,duration=.1,volume=.035){if(!soundEnabled)return;audioContext||=new AudioContext();if(audioContext.state==="suspended")audioContext.resume();const osc=audioContext.createOscillator(),gain=audioContext.createGain(),now=audioContext.currentTime;osc.type="sine";osc.frequency.setValueAtTime(freq,now);osc.frequency.exponentialRampToValueAtTime(freq*1.2,now+duration);gain.gain.setValueAtTime(volume,now);gain.gain.exponentialRampToValueAtTime(.0001,now+duration);osc.connect(gain).connect(audioContext.destination);osc.start(now);osc.stop(now+duration)}
function reset(){clearTimeout(timer);snake=[{x:8,y:9},{x:7,y:9},{x:6,y:9},{x:5,y:9}];food=placeFood(snake,W,H);direction={x:1,y:0};queued={x:1,y:0};score=0;running=false;paused=false;ended=false;$("#gameOver").hidden=true;$("#pauseBtn").textContent="暂停";$("#status").textContent="按方向键或滑动开始";$(".state").className="state";updateInfo();draw()}
function setMode(next){speed=next;$("#modeSelect").hidden=true;$("#levelLabel").textContent=`${SPEEDS[speed].name} · ${speed==="relaxed"?"轻松":speed==="normal"?"标准":"高速"}`;reset()}
function setDirection(next){if(ended)return;if(next.x===-direction.x&&next.y===-direction.y)return;queued=next;if(!running){running=true;paused=false;$("#status").textContent="小青正在竹间穿行";$(".state").className="state running";schedule()}}
function schedule(){clearTimeout(timer);if(!running||paused||ended)return;const acceleration=Math.min(45,Math.floor(score/5)*6);timer=setTimeout(tick,Math.max(48,SPEEDS[speed].delay-acceleration))}
function tick(){direction=queued;const outcome=stepSnake(snake,direction,food,W,H);if(outcome.collided){gameOver();return}snake=outcome.snake;if(outcome.ate){score++;food=placeFood(snake,W,H);tone(620+Math.min(score,12)*25,.12,.04);if(score%5===0)toast("风更快了")}updateInfo();draw();schedule()}
function updateInfo(){best=Math.max(best,score);localStorage.setItem("bambooSnakeBest",best);$("#score").textContent=score;$("#best").textContent=best;$("#lengthLabel").textContent=`身长 ${snake.length} 节`}
function roundRect(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function draw(){ctx.clearRect(0,0,canvas.width,canvas.height);const bg=ctx.createLinearGradient(0,0,canvas.width,canvas.height);bg.addColorStop(0,"#173b32");bg.addColorStop(1,"#081e1c");ctx.fillStyle=bg;ctx.fillRect(0,0,canvas.width,canvas.height);ctx.strokeStyle="#d7c2820d";ctx.lineWidth=1;for(let x=0;x<=W;x++){ctx.beginPath();ctx.moveTo(x*CELL,0);ctx.lineTo(x*CELL,canvas.height);ctx.stroke()}for(let y=0;y<=H;y++){ctx.beginPath();ctx.moveTo(0,y*CELL);ctx.lineTo(canvas.width,y*CELL);ctx.stroke()}if(food){const x=food.x*CELL+15,y=food.y*CELL+16;ctx.fillStyle="#6b9d54";ctx.save();ctx.translate(x,y-10);ctx.rotate(-.5);ctx.fillRect(0,0,3,10);ctx.restore();ctx.fillStyle="#ef7462";ctx.beginPath();ctx.arc(x-5,y,9,0,Math.PI*2);ctx.arc(x+5,y,9,0,Math.PI*2);ctx.fill();ctx.fillStyle="#ffd7b2";ctx.beginPath();ctx.arc(x-5,y-3,2.5,0,Math.PI*2);ctx.fill()}for(let i=snake.length-1;i>=0;i--){const part=snake[i],x=part.x*CELL+3,y=part.y*CELL+3;ctx.fillStyle=i===0?"#79bd70":`hsl(${135-i*.7} 36% ${48-Math.min(i,18)*.7}%)`;ctx.shadowColor=i===0?"#8ce783":"transparent";ctx.shadowBlur=i===0?12:0;roundRect(x,y,24,24,8)}ctx.shadowBlur=0;const head=snake[0],cx=head.x*CELL+15,cy=head.y*CELL+15,px=-direction.y*5,py=direction.x*5,fx=direction.x*6,fy=direction.y*6;ctx.fillStyle="#071611";for(const side of[-1,1]){ctx.beginPath();ctx.arc(cx+fx+px*side,cy+fy+py*side,2.4,0,Math.PI*2);ctx.fill()}ctx.fillStyle="#fff7d8";ctx.beginPath();ctx.arc(cx+fx+px,cy+fy+py,0.8,0,Math.PI*2);ctx.arc(cx+fx-px,cy+fy-py,0.8,0,Math.PI*2);ctx.fill()}
function togglePause(){if(!running||ended)return;paused=!paused;$("#pauseBtn").textContent=paused?"继续":"暂停";$("#status").textContent=paused?"小青歇一会儿":"小青正在竹间穿行";$(".state").className=paused?"state paused":"state running";if(!paused)schedule();else clearTimeout(timer)}
function gameOver(){ended=true;running=false;clearTimeout(timer);tone(150,.35,.04);$(".state").className="state";$("#status").textContent="小青撞晕了";$("#finalScore").textContent=score;$("#finalDetail").textContent=`吃到 ${score} 颗桃子，身长 ${snake.length} 节。`;setTimeout(()=>$("#gameOver").hidden=false,350)}
function toast(text){clearTimeout(toastTimer);$("#toast").textContent=text;$("#toast").classList.add("show");toastTimer=setTimeout(()=>$("#toast").classList.remove("show"),1300)}
const keys={ArrowUp:{x:0,y:-1},w:{x:0,y:-1},W:{x:0,y:-1},ArrowDown:{x:0,y:1},s:{x:0,y:1},S:{x:0,y:1},ArrowLeft:{x:-1,y:0},a:{x:-1,y:0},A:{x:-1,y:0},ArrowRight:{x:1,y:0},d:{x:1,y:0},D:{x:1,y:0}};addEventListener("keydown",event=>{if(keys[event.key]){event.preventDefault();setDirection(keys[event.key])}if(event.key===" "){event.preventDefault();togglePause()}});canvas.addEventListener("pointerdown",event=>touchStart={x:event.clientX,y:event.clientY});canvas.addEventListener("pointerup",event=>{if(!touchStart)return;const dx=event.clientX-touchStart.x,dy=event.clientY-touchStart.y;touchStart=null;if(Math.max(Math.abs(dx),Math.abs(dy))<20)return;setDirection(Math.abs(dx)>Math.abs(dy)?{x:Math.sign(dx),y:0}:{x:0,y:Math.sign(dy)})});document.querySelectorAll("[data-dir]").forEach(button=>button.addEventListener("click",()=>setDirection(keys[`Arrow${button.dataset.dir[0].toUpperCase()+button.dataset.dir.slice(1)}`])));document.querySelectorAll("[data-speed]").forEach(button=>button.addEventListener("click",()=>setMode(button.dataset.speed)));$("#pauseBtn").addEventListener("click",togglePause);$("#newBtn").addEventListener("click",reset);$("#againBtn").addEventListener("click",reset);$("#speedBtn").addEventListener("click",()=>{$("#gameOver").hidden=true;$("#modeSelect").hidden=false});$("#soundBtn").addEventListener("click",event=>{soundEnabled=!soundEnabled;sessionStorage.setItem("bambooSnakeSound",soundEnabled?"on":"off");event.currentTarget.textContent=soundEnabled?"♪":"×";if(soundEnabled)tone(620)});document.addEventListener("visibilitychange",()=>{if(document.hidden&&running&&!paused)togglePause()});$("#best").textContent=best;reset();
